/**
 * @file regionsRuntime.ts
 * Mutable runtime registries for world regions (REGIONS, ELITE_FOURS, zone i18n).
 * Populated at boot by johto/hoenn/sinnoh register*Data; synced to globalThis for legacy JS.
 */

import type { RegionMapEntry, RegionRegistries } from '../types/game.js';
import { ZONES, ZONE_POKEMON } from '../../constants/balance/zonesAndPacing.js';
import {
    ARENAS,
    ZONE_ID_TO_ARENA_ID,
    GYM_ZONE_TRAINERS,
    ARENA_TRAINER_POKEMON_EXTRA,
    ACCOUNT_TALENTS,
    ELITE_FOUR_GEN1,
    ELITE_FOUR_GEN2,
    ELITE_FOUR_GEN3,
    ELITE_FOUR_GEN4,
    ELITE_FOUR_GEN5,
    ELITE_FOUR_GEN6,
    ELITE_FOUR_GEN7,
    ELITE_FOUR_GEN8,
    ELITE_FOUR_GEN9,
    ELITE_FOURS,
} from '../../constants/balance/arenasTrainers.js';

export const regionsRuntime = {
    REGIONS: {} as Record<string, RegionMapEntry>,
    ELITE_FOURS: { ...ELITE_FOURS } as Record<string, unknown>,
    EXTRA_ZONE_NAME_I18N: {} as Record<string, Record<string, unknown>>,
};

/** Build registries object for registerJohto/Hoenn/SinnohData (mutates regionsRuntime). */
export function getRegionRegistries(): RegionRegistries {
    return {
        ZONES,
        ZONE_POKEMON,
        ARENAS,
        ZONE_ID_TO_ARENA_ID,
        GYM_ZONE_TRAINERS,
        ARENA_TRAINER_POKEMON_EXTRA,
        ACCOUNT_TALENTS,
        REGIONS: regionsRuntime.REGIONS,
        ELITE_FOURS: regionsRuntime.ELITE_FOURS,
        EXTRA_ZONE_NAME_I18N: regionsRuntime.EXTRA_ZONE_NAME_I18N,
    };
}

/** Expose runtime region state to legacy globalThis consumers (zoneSystem, zoneDisplay.js, save). */
export function syncRegionsToGlobal(): void {
    const g = globalThis as Record<string, unknown>;
    g.REGIONS = regionsRuntime.REGIONS;
    g.ELITE_FOURS = regionsRuntime.ELITE_FOURS;
    g.EXTRA_ZONE_NAME_I18N = regionsRuntime.EXTRA_ZONE_NAME_I18N;
    g.ELITE_FOUR_GEN1 = ELITE_FOUR_GEN1;
    g.ELITE_FOUR_GEN2 = ELITE_FOUR_GEN2;
    g.ELITE_FOUR_GEN3 = ELITE_FOUR_GEN3;
    g.ELITE_FOUR_GEN4 = ELITE_FOUR_GEN4;
    g.ELITE_FOUR_GEN5 = ELITE_FOUR_GEN5;
    g.ELITE_FOUR_GEN6 = ELITE_FOUR_GEN6;
    g.ELITE_FOUR_GEN7 = ELITE_FOUR_GEN7;
    g.ELITE_FOUR_GEN8 = ELITE_FOUR_GEN8;
    g.ELITE_FOUR_GEN9 = ELITE_FOUR_GEN9;
}

export function getRegions(): Record<string, RegionMapEntry> {
    return regionsRuntime.REGIONS;
}

export function getEliteFours(): Record<string, unknown> {
    return regionsRuntime.ELITE_FOURS;
}

export function getExtraZoneNameI18n(): Record<string, Record<string, unknown>> {
    return regionsRuntime.EXTRA_ZONE_NAME_I18N;
}
